import json,sys,statistics as st,collections,math,random,html
from pathlib import Path
p=Path(sys.argv[1]);rows=[json.loads(x) for x in (p/'games.jsonl').read_text().splitlines()]
assert len(rows)==60
mean=lambda a:round(st.mean(a),2) if a else None
quant=lambda a,q:sorted(a)[min(len(a)-1,int(len(a)*q))] if a else None
rng=random.Random(139)
def interval(a,keys=None):
 if not a:return None
 groups=collections.defaultdict(list)
 for key,value in zip(keys if keys is not None else range(len(a)),a):groups[key].append(value)
 ids=list(groups);b=[]
 for _ in range(3000):
  sample=[v for key in rng.choices(ids,k=len(ids)) for v in groups[key]];b.append(st.mean(sample))
 b.sort();return [round(b[75],2),round(b[2924],2)]
def wilson(k,n):
 z=1.96;d=1+z*z/n;c=(k/n+z*z/(2*n))/d;w=z*math.sqrt(k/n*(1-k/n)/n+z*z/(4*n*n))/d;return [round(100*(c-w),1),round(100*(c+w),1)]
def summary(a):
 f=[r for r in a if r.get('endReason')=='finish'];prices=[v for r in a for v in r.get('prices',[])];return {'games':len(a),'finished':len(f),'censored':sum(r['status']=='censored' for r in a),'stalled':sum(r['status']=='stalled' for r in a),'failed':sum(r['status']=='failed' for r in a),'range':mean([r['range'] for r in f]),'range95':interval([r['range'] for r in f],[r['seed'] for r in f]),'third':mean([r['thirdLag'] for r in f]),'medianActions':st.median([r['actions'] for r in f]) if f else None,'p90Actions':quant([r['actions'] for r in f],.9),'medianRounds':st.median([r['rounds'] for r in f]) if f else None,'zeroPayout':mean([r['zero'] for r in f]),'auctionMean':mean(prices),'auctionMedian':st.median(prices) if prices else None,'auctionP90':quant(prices,.9),'oneCoinSales':sum(v==1 for v in prices),'sales':len(prices)}
baselines={v:[json.loads(x) for x in (p/f'baseline-v{v}.jsonl').read_text().splitlines()] for v in [137,138]};versions={**baselines,139:rows};metrics={'overall':summary(rows),'byPlayers':[{'players':n,**summary([r for r in rows if r['players']==n])} for n in [2,3,4]],'policies':[{'cohort':c,**summary([r for r in rows if r['cohort']==c])} for c in ['self','mixed']]};metrics['comparison']=[{'version':v,'players':n,**summary([r for r in rs if n=='all' or r['players']==n])} for v,rs in versions.items() for n in ['all',2,3,4]]
metrics['matched']=[]
for v,rs in baselines.items():
 old={(r['seed'],r['players'],r['cohort']):r for r in rs};pairs=[(old[(r['seed'],r['players'],r['cohort'])],r) for r in rows if r.get('endReason')=='finish' and old[(r['seed'],r['players'],r['cohort'])].get('endReason')=='finish'];metrics['matched'].append({'baseline':v,'pairs':len(pairs),'oldRange':mean([a['range'] for a,b in pairs]),'newRange':mean([b['range'] for a,b in pairs]),'rangeDelta95':interval([b['range']-a['range'] for a,b in pairs],[b['seed'] for a,b in pairs]),'oldThird':mean([a['thirdLag'] for a,b in pairs]),'newThird':mean([b['thirdLag'] for a,b in pairs])})
f=[r for r in rows if r.get('endReason')=='finish'];metrics['actions']={t:mean([r['types'][t] for r in f]) for t in ['call','valueAction','changeFounder','raiseMoney']};metrics['values']=dict(collections.Counter(v for r in rows for v in r.get('values',[])));founders={}
for r in rows:
 for fid,v in r.get('founderMovement',{}).items():
  a=founders.setdefault(fid,{'founder':fid,'gamesWithMovement':0,'forward':0,'backward':0});a['gamesWithMovement']+=1;a['forward']+=v['forward'];a['backward']+=v['backward']
metrics['founders']=sorted(founders.values(),key=lambda r:-r['forward']);metrics['cutoffs']=[{k:r.get(k) for k in ['seed','players','cohort','status','cutoff','positions','actions']} for r in rows if r['status']!='complete'];metrics['meanCardsSpent']=mean([54-r['deck']-sum(r['hands']) for r in f]);metrics['meanUnspent']=mean([r['deck']+sum(r['hands']) for r in f]);(p/'metrics.json').write_text(json.dumps(metrics,indent=2));print(json.dumps(metrics,indent=2))
if not (p/'sample-review.json').exists():sys.exit()
reviews=json.loads((p/'sample-review.json').read_text());attempts=json.loads((p/'sample-index.json').read_text());manifest=json.loads((p/'manifest.json').read_text());e=html.escape
T=lambda rs,ks:'<table><tr>'+''.join('<th>'+e(k)+'</th>' for k in ks)+'</tr>'+''.join('<tr>'+''.join('<td>'+e(str(r.get(k,'—')))+'</td>' for k in ks)+'</tr>' for r in rs)+'</table>'
a=metrics['overall'];body=f'<h1>v139 · Did the shared reveal improve the game?</h1><p>run-01 · {e(manifest["created"])} · nine cards per company · 60 primary games</p><p><b>{a["finished"]}/60 reached 24; {a["censored"]} censored; {a["failed"]} errors.</b> This measures the new rules plus the current bot adaptation, not an isolated causal effect of reveal timing.</p>'
body+='<h2>Compared with the two previous versions</h2><p>v137: immediate growth, support actions free. v138: every action spends a card, with one bland die after support actions. v139: support actions free, one fundraising auction/company/round, shared classic founder reveal, higher payout curve.</p>'+T([r for r in metrics['comparison'] if r['players']=='all'],['version','finished','censored','stalled','range','third','medianActions','p90Actions','zeroPayout'])
body+='<p>Spread, duration and zero-payout counts above include only games reaching 24. Do not mistake early cutoffs for tight finishes. v137 capital-only research cutoffs differ from v139’s 2,000-command cap; no capital-only cutoff is valid here because global founders can still move companies.</p>'
body+='<h2>By player count</h2>'+T(metrics['byPlayers'],['players','games','finished','censored','range','range95','third','medianActions','p90Actions','medianRounds','zeroPayout'])+'<p>range = first–last; third = first–third. Bootstrap intervals resample setup-seed clusters, keeping matching lineups/counts together within the displayed group; they describe this small seed/policy cohort, not optimal human play. Mixed lineups sometimes omit the random seat in 2/3-player games, yielding duplicates of deterministic self-play; these are not 60 independent setups. Only ten primary setup seeds were tested.</p>'
body+='<h2>Matched completed games</h2>'+T(metrics['matched'],['baseline','pairs','oldRange','newRange','rangeDelta95','oldThird','newThird'])+'<p>Only seeds/player counts/lineups that finish in both versions are included. This selected subset checks whether survivor composition alone explains the difference; it is not an unbiased all-game effect. RNG paths diverge after decisions change.</p>'
body+='<h2>What the samples show</h2>'+ (p/'findings.html').read_text()
body+='<details><summary>Actions, economy and policies</summary>'+T([metrics['actions']],list(metrics['actions']))+f'<p>Mean ordinary deal-flow cards spent in finishers: {metrics["meanCardsSpent"]}; mean cards still in hands/deck: {metrics["meanUnspent"]}. Public share grants and auctions can issue shares without consuming the corresponding company’s deal-flow card.</p>'+T(metrics['policies'],['cohort','games','finished','censored','range','third','auctionMean','auctionMedian','auctionP90','oneCoinSales','sales'])+'<p>Prices include sold auctions across all attempts. Balanced, growth and saver currently execute the same non-random policy; mixed play tests inclusion of a random stress seat, not four independently tuned strategies. Random bids span affordable cash amounts and can be reckless. No policy-strength ranking follows.</p></details>'
body+='<details><summary>Founder and value usage</summary><p>Raw counts across all attempts, including censored games. Founder ledger includes setup; attribution can overlap. These are usage/movement data, not exposure-normalized causal card strength.</p>'+T([{'card':k,'plays':v} for k,v in sorted(metrics['values'].items(),key=lambda x:-x[1])],['card','plays'])+T(metrics['founders'],['founder','gamesWithMovement','forward','backward'])+'</details>'
body+='<h2>Ten complete trace reviews</h2><p>Four-player slots 8301–8310 alternate self/mixed; up to five attempts per slot (add 100 after noncompletion). Selection uses completion only. All attempts retained; each saved trace is replayed to identical logs and scores. These samples are excluded from primary aggregates.</p>'
for r in reviews:body+=f'<details><summary>Seed {r["seed"]}</summary><p>{e(r["review"])}</p><a href="samples/{r["seed"]}.json">Full trace and decisions</a> · <a href="samples/{r["seed"]}-replay.json">Replay</a></details>'
body+='<details><summary>Unfinished games and reproducibility</summary>'+T(metrics['cutoffs'],['seed','players','cohort','status','cutoff','actions','positions'])+f'<p>Source SHA-256: {manifest["source"]}</p><p>Targets remain provisional: ≥95% reach24, mean range≤16, first–third≤8. Bot forecasts model local purchases and global founder effects but not the full joint outcome of all later queued purchases. That limitation can distort bidding and endgame decisions. No rules or bot changes were made during this study.</p><p><a href="manifest.json">Manifest</a> · <a href="metrics.json">Metrics</a> · <a href="games.jsonl">Primary records</a> · <a href="sample-index.json">All sample attempts</a> · <a href="runtime.json">Runtime</a> · <a href="source/scripts/round-reveal-study.js">Frozen runner</a></p><pre>node scripts/round-reveal-study.js NEW_DIRECTORY\npython3 scripts/reveal-study-report.py NEW_DIRECTORY</pre><p>Rendering requires baseline copies, sample-review.json and findings.html bundled here. Frozen source contains the production engine and bots used in this run.</p></details>'
(p/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v139 shared-reveal results</title><style>body{font:17px/1.55 system-ui;max-width:1080px;margin:40px auto;padding:0 24px;background:#f8f6ef;color:#243029}h1{line-height:1.2}table{border-collapse:collapse;display:block;overflow:auto;font-size:14px}td,th{padding:8px;border-bottom:1px solid #ccc;text-align:left}details{margin:18px 0;padding:16px;background:white;border:1px solid #ccc;border-radius:8px}summary{font-weight:bold;cursor:pointer}a{color:#17624a}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>'+body+'</html>')
